import{_ as e,o as a,c as n,a2 as t}from"./chunks/framework.DiXyETtc.js";const y=JSON.parse('{"title":"Agent State","description":"","frontmatter":{},"headers":[],"relativePath":"guide/state.md","filePath":"guide/state.md","lastUpdated":1795686328000}'),o={name:"guide/state.md"};function l(p,s,c,r,E,i){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="agent-state" tabindex="-1">Agent State <a class="header-anchor" href="#agent-state" aria-label="Permalink to &quot;Agent State&quot;">​</a></h1><p>Each agent has state that outlives its runs: a key-value store and typed document collections. State is scoped to the agent name and lives in the store.</p><h2 id="declaring-collections" tabindex="-1">Declaring collections <a class="header-anchor" href="#declaring-collections" aria-label="Permalink to &quot;Declaring collections&quot;">​</a></h2><p>Declare collections with any <a href="https://standardschema.dev" target="_blank" rel="noreferrer">Standard Schema</a>, such as a zod schema:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> loop = z.object({</span></span>
<span class="line"><span style="color:#E3E5EA;">    title: z.string(),</span></span>
<span class="line"><span style="color:#E3E5EA;">    status: z.enum([</span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">&#39;resolved&#39;</span><span style="color:#E3E5EA;">]),</span></span>
<span class="line"><span style="color:#E3E5EA;">    due: z.string().optional(),</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> digest = defineModelAgent({</span></span>
<span class="line"><span style="color:#E3E5EA;">    name: </span><span style="color:#E7C58C;">&#39;digest&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    model,</span></span>
<span class="line"><span style="color:#E3E5EA;">    instructions: </span><span style="color:#E7C58C;">&#39;Track open loops across days.&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    state: { loops: loop },</span></span>
<span class="line"><span style="color:#E3E5EA;">    tools: ({ state }) </span><span style="color:#8EA7FF;">=&gt;</span><span style="color:#E3E5EA;"> ({</span></span>
<span class="line"><span style="color:#E3E5EA;">        countOpenLoops: tool({</span></span>
<span class="line"><span style="color:#E3E5EA;">            description: </span><span style="color:#E7C58C;">&#39;Counts the open loops.&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">            inputSchema: z.object({}),</span></span>
<span class="line"><span style="color:#E3E5EA;">            execute: </span><span style="color:#8EA7FF;">async</span><span style="color:#E3E5EA;"> () </span><span style="color:#8EA7FF;">=&gt;</span><span style="color:#E3E5EA;"> {</span></span>
<span class="line"><span style="color:#8EA7FF;">                const</span><span style="color:#E3E5EA;"> open = </span><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> state.collection(</span><span style="color:#E7C58C;">&#39;loops&#39;</span><span style="color:#E3E5EA;">).list({ where: { status: </span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E3E5EA;"> } });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">                return</span><span style="color:#E3E5EA;"> open.length;</span></span>
<span class="line"><span style="color:#E3E5EA;">            },</span></span>
<span class="line"><span style="color:#E3E5EA;">        }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    }),</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span></code></pre></div><p>A <code>tools</code> factory receives <code>state</code>, typed by the declared schema. A tool built with <code>defineTool()</code> reads it as <code>context.state</code> (<code>defineTool&lt;Input, Output, typeof schema&gt;</code> types it).</p><h2 id="the-state-api" tabindex="-1">The state API <a class="header-anchor" href="#the-state-api" aria-label="Permalink to &quot;The state API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>state.get&lt;T&gt;(key)</code></td><td>Reads a value, <code>undefined</code> when absent</td></tr><tr><td><code>state.set(key, value)</code></td><td>Writes a value</td></tr><tr><td><code>state.collection(name).list({ where?, limit? })</code></td><td>Lists documents as <code>{ id, ...doc }</code>; <code>where</code> matches top-level fields by equality</td></tr><tr><td><code>state.collection(name).upsert(id, doc)</code></td><td>Validates <code>doc</code> with the collection&#39;s schema, then creates or replaces it</td></tr><tr><td><code>state.collection(name).remove(id)</code></td><td>Deletes a document</td></tr></tbody></table><p><code>upsert</code> stores the schema&#39;s output. A document that fails validation throws <code>ValidationError</code> and nothing is stored; its <code>issues</code> hold the validation issues with their paths. Only declared collections are writable. Once the execution ended (the run settled or paused), a write from work a tool left behind throws <code>InvalidRunStateError</code> and stores nothing; a call that has not returned yet, such as a cleanup after the abort, can still write. Reads stay open.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">try</span><span style="color:#E3E5EA;"> {</span></span>
<span class="line"><span style="color:#8EA7FF;">    await</span><span style="color:#E3E5EA;"> state.collection(</span><span style="color:#E7C58C;">&#39;loops&#39;</span><span style="color:#E3E5EA;">).upsert(</span><span style="color:#E7C58C;">&#39;x&#39;</span><span style="color:#E3E5EA;">, { title: </span><span style="color:#E7C58C;">&#39;Call Bob&#39;</span><span style="color:#E3E5EA;">, status: </span><span style="color:#E7C58C;">&#39;later&#39;</span><span style="color:#8EA7FF;"> as</span><span style="color:#E7C58C;"> &#39;open&#39;</span><span style="color:#E3E5EA;"> });</span></span>
<span class="line"><span style="color:#E3E5EA;">} </span><span style="color:#8EA7FF;">catch</span><span style="color:#E3E5EA;"> (error) {</span></span>
<span class="line"><span style="color:#8EA7FF;">    if</span><span style="color:#E3E5EA;"> (error </span><span style="color:#8EA7FF;">instanceof</span><span style="color:#E3E5EA;"> ValidationError) {</span></span>
<span class="line"><span style="color:#8EA7FF;">        for</span><span style="color:#E3E5EA;"> (</span><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> issue </span><span style="color:#8EA7FF;">of</span><span style="color:#E3E5EA;"> error.issues) {</span></span>
<span class="line"><span style="color:#E3E5EA;">            console.log(issue.path, issue.message);</span></span>
<span class="line"><span style="color:#E3E5EA;">        }</span></span>
<span class="line"><span style="color:#E3E5EA;">    }</span></span>
<span class="line"><span style="color:#E3E5EA;">}</span></span></code></pre></div><p><code>createAgentState(agent, schema, stateService)</code> builds the same API outside a run (<code>engine.stateService</code>, or a <code>StateService</code> on any state repositories), for scripts, admin tasks and tests:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#80858F;">// the state service of an engine (\`engine.stateService\`), here on memory repositories</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> registry = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> MemoryRegistry();</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> service = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> StateService({</span></span>
<span class="line"><span style="color:#E3E5EA;">    repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> MemoryStateRepository({ registry }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    documentRepository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> MemoryStateDocumentRepository({ registry }),</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> state = createAgentState(</span><span style="color:#E7C58C;">&#39;digest&#39;</span><span style="color:#E3E5EA;">, { loops: loop }, service);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> state.set(</span><span style="color:#E7C58C;">&#39;lastUid&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">1042</span><span style="color:#E3E5EA;">);</span></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> state.get&lt;number&gt;(</span><span style="color:#E7C58C;">&#39;lastUid&#39;</span><span style="color:#E3E5EA;">); </span><span style="color:#80858F;">// 1042</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> loops = state.collection(</span><span style="color:#E7C58C;">&#39;loops&#39;</span><span style="color:#E3E5EA;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> loops.upsert(</span><span style="color:#E7C58C;">&#39;reply-anna&#39;</span><span style="color:#E3E5EA;">, { title: </span><span style="color:#E7C58C;">&#39;Reply to Anna&#39;</span><span style="color:#E3E5EA;">, status: </span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E3E5EA;"> });</span></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> loops.list({ where: { status: </span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E3E5EA;"> }, limit: </span><span style="color:#E7C58C;">10</span><span style="color:#E3E5EA;"> });</span></span>
<span class="line"><span style="color:#80858F;">// [{ id: &#39;reply-anna&#39;, title: &#39;Reply to Anna&#39;, status: &#39;open&#39; }]</span></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> loops.remove(</span><span style="color:#E7C58C;">&#39;reply-anna&#39;</span><span style="color:#E3E5EA;">);</span></span></code></pre></div><h2 id="generated-tools" tabindex="-1">Generated tools <a class="header-anchor" href="#generated-tools" aria-label="Permalink to &quot;Generated tools&quot;">​</a></h2><p>With a <code>state</code> schema, the model gets three tools per collection:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Kind</th><th>Input</th></tr></thead><tbody><tr><td><code>state_&lt;collection&gt;_list</code></td><td>plain tool</td><td><code>{ where?, limit? }</code></td></tr><tr><td><code>state_&lt;collection&gt;_upsert</code></td><td>effect tool</td><td><code>{ id, doc }</code> (the doc&#39;s JSON Schema, when the schema can produce one)</td></tr><tr><td><code>state_&lt;collection&gt;_remove</code></td><td>effect tool</td><td><code>{ id }</code></td></tr></tbody></table><p>An invalid document becomes a tool error the model can correct. Each write gets its own effect key, so a replayed <code>upsert A, upsert B, upsert A</code> sequence still ends on the last write. Your own tools win on a name clash. <code>createStateTools(schema)</code> builds these tools directly; they read the state from their <code>context.state</code>, so call them with a <code>ToolContext</code> (see <a href="/guide/effect-tools#outside-the-engine"><code>wrapToolsForRun</code></a>).</p>`,17)])])}const h=e(o,[["render",l]]);export{y as __pageData,h as default};
